type ToastManager<Data extends {} = any> = {
    ' subscribe': (listener: (data: ToastManagerEvent) => void) => () => void;
    add: <T extends Data = Data>(options: ToastManagerAddOptions<T>) => string;
    close: (id?: string) => void;
    update: <T extends Data = Data>(id: string, updates: ToastManagerUpdateOptions<T> | ((prevToast: ToastObject<T>) => ToastManagerUpdateOptions<T>)) => void;
    promise: <Value, T extends Data = Data>(promiseValue: Promise<Value>, options: ToastManagerPromiseOptions<Value, T>) => Promise<Value>;
};

type ToastManagerAddOptions<Data extends {}> = {
    id?: string;
    title?: React.ReactNode;
    type?: string;
    description?: React.ReactNode;
    timeout?: number;
    priority?: 'low' | 'high';
    transitionStatus?: 'starting' | 'ending';
    onClose?: () => void;
    onRemove?: () => void;
    actionProps?: Omit<React.DetailedHTMLProps<React.ButtonHTMLAttributes<HTMLButtonElement>, HTMLButtonElement>, 'ref'>;
    positionerProps?: ToastManagerPositionerProps;
    data?: Data;
};

type ToastManagerEvent = {
    action: 'add' | 'close' | 'update' | 'promise';
    options: any;
};

type ToastManagerPositionerProps = {
    anchor?: Element | null;
    style?: React.CSSProperties | ((state: Toast.Positioner.State) => React.CSSProperties | undefined);
    className?: string | ((state: Toast.Positioner.State) => string | undefined);
    side?: Side;
    positionMethod?: 'absolute' | 'fixed';
    sideOffset?: number | OffsetFunction;
    align?: Align;
    alignOffset?: number | OffsetFunction;
    collisionBoundary?: Boundary;
    collisionPadding?: Padding;
    sticky?: boolean;
    arrowPadding?: number;
    disableAnchorTracking?: boolean;
    collisionAvoidance?: CollisionAvoidance;
    render?: ReactElement | ((props: HTMLProps, state: Toast.Positioner.State) => ReactElement);
};

type ToastManagerPromiseOptions<Value, Data extends {}> = {
    loading: string | ToastManagerAddOptions<Data>;
    success: string | ToastManagerUpdateOptions<Data> | ((result: Value) => string | ToastManagerUpdateOptions<Data>);
    error: string | ToastManagerUpdateOptions<Data> | ((error: any) => string | ToastManagerUpdateOptions<Data>);
};

type ToastManagerUpdateOptions<Data extends {}> = {
    title?: React.ReactNode;
    type?: string;
    description?: React.ReactNode;
    timeout?: number;
    priority?: 'low' | 'high';
    onClose?: () => void;
    onRemove?: () => void;
    actionProps?: Omit<React.DetailedHTMLProps<React.ButtonHTMLAttributes<HTMLButtonElement>, HTMLButtonElement>, 'ref'>;
    positionerProps?: ToastManagerPositionerProps;
